mapper.sql:
WHERE d.is_deleted = 0
  AND UPPER(e.class_enum) IN ('INPATIENT', 'IMP')

    AND stay.ward_id = #{query.wardId}


    AND (p.name LIKE CONCAT('%', #{query.patientKeyword}, '%')
         OR e.bus_no LIKE CONCAT('%', #{query.patientKeyword}, '%'))


    AND stay.bed_no LIKE CONCAT('%', #{query.bedNo}, '%')


    AND d.status_enum = #{query.statusEnum}


    AND d.dispense_enum = #{query.dispenseEnum}


    AND d.dispense_time >= #{query.startTime}


    AND d.dispense_time <= IF(
        LENGTH(#{query.endTime}) = 10,
        CONCAT(#{query.endTime}, ' 23:59:59'),
        #{query.endTime}
    )


    AND (m.name LIKE CONCAT('%', #{query.drugKeyword}, '%')
         OR m.py_str LIKE CONCAT('%', #{query.drugKeyword}, '%')
         OR m.wb_str LIKE CONCAT('%', #{query.drugKeyword}, '%'))

mapper.select:
SELECT



ORDER BY d.dispense_time DESC, d.id DESC
LIMIT #{limit}
